class MyThread extends Thread {
    MyThread(String name) { super(name); }
    @Override
    public void run() {
        System.out.println(getName() + " w watku: " + Thread.currentThread().getName());
    }
}
MyThread t = new MyThread("Watek-A");
t.start();
t.join();

MyThread w = new MyThread("A");
w.start();
w.join();
try {
    w.start(); // watek juz zakonczony!
} catch (IllegalThreadStateException e) {
    System.out.println("Blad: " + e);
}

