Thread createWorker(String type, int[] data) {
    return switch (type) {
        case "SUM" -> new SumThread(data);
        case "MAX" -> new MaxThread(data);
        case "MIN" -> new MinThread(data);
        default -> throw new IllegalArgumentException(type);
    };
}

class ChainThread extends Thread {
    int poziom;
    ChainThread(int p) { poziom = p; }
    public void run() {
        System.out.println("poziom " + poziom);
        if (poziom > 0) {
            ChainThread nastepny = new ChainThread(poziom - 1);
            nastepny.start();
            try { nastepny.join(); } catch (InterruptedException e) {}
        }
    }
}
new ChainThread(5).start();

class RetryThread extends Thread {
    Random r = new Random(42);
    public void run() {
        for (int proba = 1; proba <= 3; proba++) {
            if (r.nextBoolean()) { System.out.println("Sukces przy probie " + proba); return; }
        }
        System.out.println("Ostateczna porazka po 3 probach");
    }
}

class ParentThread extends Thread {
    public void run() {
        for (int i = 0; i < 3; i++) {
            ChildThread c = new ChildThread(i);
            c.start();
            try { c.join(); } catch (InterruptedException e) {}
        }
        System.out.println("Rodzic zakonczyl, 3 dzieci wykonane");
    }
}

