class RangeSumThread extends Thread {
    int od, doo; long wynik;
    RangeSumThread(int od, int doo) { this.od = od; this.doo = doo; }
    public void run() { long s = 0; for (int i = od; i <= doo; i++) s += i; wynik = s; }
}
// podziel 1..1_000_000 na 4 czesci, uruchom, join, zsumuj wynik z kazdego

class FactorialThread extends Thread {
    int n; Runnable callback; long wynik;
    FactorialThread(int n, Runnable callback) { this.n = n; this.callback = callback; }
    public void run() {
        wynik = 1; for (int i = 2; i <= n; i++) wynik *= i;
        callback.run();
    }
}
FactorialThread t = new FactorialThread(6, () -> System.out.println("Wynik gotowy"));
t.start(); t.join();

