abstract class ResultThread<T> extends Thread {
    protected T result;
    T getResult() { return result; }
}
class SumResultThread extends ResultThread<Long> {
    public void run() { long s=0; for (int i=1;i<=10;i++) s+=i; result = s; }
}
class ProductResultThread extends ResultThread<Long> {
    public void run() { long p=1; for (int i=1;i<=10;i++) p*=i; result = p; }
}
SumResultThread s = new SumResultThread(); ProductResultThread p = new ProductResultThread();
s.start(); p.start(); s.join(); p.join();
System.out.println(s.getResult() + " " + p.getResult());
